/**
 * useTables Hook
 *
 * Custom hook for managing restaurant table CRUD operations and state.
 * Provides methods for fetching, creating, updating, and deleting tables.
 *
 * Usage:
 *   const { tables, isLoading, error, fetchTables, createTable, updateTable, deleteTable, updateStatus } = useTables(organizationId)
 */

import { useState, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { RestaurantTable, TableStatus } from '@/types/database'

/**
 * Table form data interface
 */
export interface TableFormData {
  table_number: string
  current_status?: TableStatus
}

/**
 * Hook return type
 */
export interface UseTablesReturn {
  tables: RestaurantTable[]
  isLoading: boolean
  error: string | null
  fetchTables: () => Promise<void>
  createTable: (data: TableFormData) => Promise<string>
  updateTable: (id: string, data: TableFormData) => Promise<void>
  deleteTable: (id: string) => Promise<void>
  updateStatus: (id: string, status: TableStatus) => Promise<void>
}

/**
 * Custom hook for table management
 *
 * @param organizationId - The organization ID to fetch tables for
 * @returns Table state and CRUD methods
 */
export function useTables(organizationId: string | undefined): UseTablesReturn {
  const [tables, setTables] = useState<RestaurantTable[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  /**
   * Fetch tables for the organization
   */
  const fetchTables = useCallback(async () => {
    if (!organizationId) return

    setIsLoading(true)
    setError(null)

    try {
      const supabase = createClient()

      const { data, error: fetchError } = await supabase
        .from('restaurant_tables')
        .select('*')
        .eq('organization_id', organizationId)
        .order('table_number', { ascending: true })

      if (fetchError) throw fetchError

      setTables(data || [])
    } catch (err) {
      setError('Failed to fetch tables')
    } finally {
      setIsLoading(false)
    }
  }, [organizationId])

  /**
   * Create a new table
   */
  const createTable = useCallback(async (data: TableFormData): Promise<string> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const tableData = {
      table_number: data.table_number.trim(),
      organization_id: organizationId,
      current_status: (data.current_status || 'empty') as TableStatus,
    }

    const { data: newTable, error: insertError } = await supabase
      .from('restaurant_tables')
      .insert(tableData)
      .select()
      .single()

    if (insertError) throw insertError

    return newTable.id
  }, [organizationId])

  /**
   * Update an existing table
   */
  const updateTable = useCallback(async (id: string, data: TableFormData): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const tableData = {
      table_number: data.table_number.trim(),
    }

    const { error: updateError } = await supabase
      .from('restaurant_tables')
      .update(tableData)
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (updateError) throw updateError
  }, [organizationId])

  /**
   * Delete a table
   */
  const deleteTable = useCallback(async (id: string): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const { error: deleteError } = await supabase
      .from('restaurant_tables')
      .delete()
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (deleteError) throw deleteError
  }, [organizationId])

  /**
   * Update table status
   */
  const updateStatus = useCallback(async (id: string, status: TableStatus): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const { error: updateError } = await supabase
      .from('restaurant_tables')
      .update({ current_status: status })
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (updateError) throw updateError
  }, [organizationId])

  return {
    tables,
    isLoading,
    error,
    fetchTables,
    createTable,
    updateTable,
    deleteTable,
    updateStatus,
  }
}
